s=json.loads((R/'results/customer/summary.json').read_text())
html=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>REFLEX — Industry & evidence</title>
<style>
:root{--paper:#f4f1e9;--ink:#142838;--blue:#225dff;--muted:#5c6870;--line:#cbd0cc;--amber:#996020}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 'Avenir Next','Helvetica Neue',sans-serif}a{color:var(--blue)}nav{padding:24px 5vw;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:20px}nav b{font-size:27px;letter-spacing:-1.5px}nav span{display:flex;gap:24px;font-size:13px}main{max-width:1340px;margin:auto;padding:0 5vw}section{padding:65px 0;border-bottom:1px solid var(--line)}.eyebrow{font:12px Menlo,monospace;letter-spacing:2px;text-transform:uppercase;color:var(--blue)}h1{font:600 clamp(43px,5.3vw,78px)/1.06 'Avenir Next',sans-serif;letter-spacing:-3px;margin:22px 0;max-width:1000px}h2{font-size:36px;line-height:1.16;letter-spacing:-1.2px;margin:14px 0 26px}h3{font-size:20px;line-height:1.3;margin:15px 0}.lead{font-size:21px;max-width:790px;color:#425564}.hero{display:grid;grid-template-columns:1fr 270px;gap:45px;align-items:end}.stamp{border-left:3px solid var(--blue);padding:20px;font:13px/1.8 Menlo,monospace}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.card{border-top:2px solid var(--ink);padding-top:17px}.number{display:block;font-size:57px;line-height:1.15;letter-spacing:-2.5px;font-weight:600;margin:15px 0}.small{font-size:12px;color:var(--muted)}.tag{display:inline-block;background:#e4eaff;color:var(--blue);padding:3px 8px;font:11px Menlo,monospace;letter-spacing:.3px}.warn{color:var(--amber);background:#f6ead8}.dark{background:var(--ink);color:var(--paper);padding:32px;margin-top:30px}.dark p{color:#c9d3d7}.flow{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:25px 0}.flow b{border:1px solid #89979d;padding:12px 17px}.twocol{display:grid;grid-template-columns:1.25fr 1fr;gap:38px}.controls{display:flex;gap:18px;flex-wrap:wrap;margin:26px 0}label{font-size:13px;display:flex;flex-direction:column;gap:5px}select,input{font:inherit;color:var(--ink);background:transparent;border:1px solid #a7b0b3;border-radius:0;padding:9px 13px}button,.button{display:inline-block;background:var(--blue);color:white;border:0;text-decoration:none;padding:11px 17px;font:600 13px 'Avenir Next',sans-serif;cursor:pointer}button.secondary{background:transparent;border:1px solid var(--blue);color:var(--blue)}svg{width:100%;height:auto;display:block}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:15px 12px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{font-weight:500;font-size:11px;text-transform:uppercase;letter-spacing:.5px}td.good{color:var(--blue)}td.bad{color:var(--amber)}.scroll{overflow-x:auto}.callout{border-left:3px solid var(--amber);padding:14px 20px;background:#ede9df;margin-top:25px}.sources{font-size:13px}.sources li{margin:12px 0}footer{padding:35px 5vw;font:12px Menlo,monospace;color:var(--muted)}.meter{display:grid;grid-template-columns:130px 1fr 65px;gap:10px;align-items:center;margin:15px 0;font-size:13px}.bar{height:17px;background:#d9dfdf}.bar i{height:100%;display:block;background:var(--blue);transition:width .5s}details{margin:25px 0}summary{cursor:pointer;font-weight:600}@media(max-width:800px){.hero,.grid,.twocol{grid-template-columns:1fr}.stamp{display:none}nav span{gap:12px;flex-wrap:wrap}h1{letter-spacing:-1.5px}h2{font-size:29px}section{padding:40px 0}.number{font-size:47px}.dark{padding:20px}}
</style>
<nav><b>REFLEX<span style="color:var(--blue);display:inline">.</span></b><span><a href="#industry">Why it matters</a><a href="#benchmark">Evidence</a><a href="#value">Customer value</a><a href="http://127.0.0.1:8765/research.html">Device R&D</a><a href="http://127.0.0.1:8765/research.html">Device R&D</a><a href="http://127.0.0.1:8765/research.html">Device R&D</a><a href="http://127.0.0.1:8765/research.html">Device R&D</a><a href="https://github.com/2fe2000/reflex-metrology">GitHub ↗</a></span></nav><main>
<section><div class="eyebrow">Semiconductor manufacturing / research prototype / 11 Nov 2026</div><div class="hero"><div><h1>Measurements arrive late.<br>Production keeps moving.</h1><p class="lead">A small, local model that adapts to arriving measurements—designed for the gap between a process change and trusted feedback.</p><a class="button" href="http://127.0.0.1:8765/delay.html">Run the actual model →</a> <a href="#benchmark" style="margin-left:16px">Inspect every condition</a></div><aside class="stamp">CAUSAL UPDATES<br>PUBLIC DATA REPLAY<br>NO CLOUD REQUIRED<br>FROZEN V7 WEIGHTS<br><br>Research evidence.<br>Factory pilot next.</aside></div></section>
<section id="industry"><div class="eyebrow">01 / An industrial problem, already worth solving</div><h2>The next wafer cannot wait for every measurement.</h2><div class="flow"><b>Deposition</b>→<b>Patterning</b>→<b>Etch / CMP</b>→<b style="color:var(--blue)">Metrology</b>↩<b>Process decisions</b></div><p class="small">Simplified process illustration. Actual fabrication repeats many operations; this prototype does not simulate a complete fab.</p><div class="grid"><article class="card"><span class="tag">Industry evidence · not REFLEX</span><strong class="number">50M+</strong><h3>Wafers virtually measured</h3><p>SK hynix reported over 50 million wafers and a 29% improvement in process variability with Panoptes VM in February 2024. This demonstrates industrial relevance, not our performance.</p><a class="small" href="https://news.skhynix.com/en/gauss-labs-and-sk-hynix-present-ai-papers-at-spie-al-2024/">SK hynix primary source ↗</a></article><article class="card"><span class="tag">2026 production direction</span><h3>From prediction to equipment diagnosis</h3><p>SK hynix and Gauss Labs' 2026 work uses production data for tool-to-tool matching, early anomaly detection and explainable overlay metrology.</p><p>Established competitors already adapt models. Our opportunity must be demonstrated in delayed-feedback reliability and integration.</p><a class="small" href="https://news.skhynix.com/en/sk-hynix-and-gauss-labs-present-ai-based-semiconductor-virtual-metrology-research-at-spie-al-2026/">2026 research announcement ↗</a></article><article class="card"><span class="tag">Our focused customer hypothesis</span><h3>One chamber. A real feedback delay.</h3><p>Start with process and metrology engineers, or an equipment OEM, on one deposition or etch process. Replay real measurement timestamps after a process change; validate in shadow mode.</p><p class="small">Maintenance recovery, these specific processes and customer willingness to pay have not been validated with REFLEX.</p></article></div><div class="dark"><h3>What we built</h3><p>GRAPE baseline + timestamped residual filter + bounded Bayesian regime model. Store each requested sample's original prediction. When its label arrives, compare against that stored prediction and update the expert weights. Unarrived labels cannot enter the model.</p><div class="flow"><b>Predict at t</b>→<b>Store & request</b>→<b>Label at t + delay</b>→<b>Update at arrival</b></div><p class="small">Fixed sample-count delays; ordered arrivals. Raw sensor feature extraction, variable/out-of-order latency, process control and cross-chamber learning remain future work. No new base-algorithm claim.</p></div></section>
<section id="benchmark"><div class="eyebrow">02 / Frozen-model evidence</div><h2>Less error, with the same measurements.</h2><div class="grid"><div class="card"><span class="tag">Dataset 1 · delay 5 · 20% requests</span><strong class="number">18.81% ↓</strong><h3>Large prediction-error frequency</h3><p>15.50% → 12.58% of predictions exceed a development-defined error threshold. A 2.92 percentage-point difference.</p><p class="small">Conditional 95% interval: 5.42–30.88% relative reduction. Prediction-error proxy; not defect reduction or yield.</p></div><div class="card"><span class="tag">Same condition</span><strong class="number">12.05% ↓</strong><h3>P90 absolute prediction error</h3><p>The error level covering 90% of predictions improved. Mean RMSE across all four delayed conditions improved 1.03%.</p><p class="small">The original 10% mean-RMSE target was not met. Evaluation streams were repeatedly inspected during development.</p></div><div class="card"><span class="tag">Measured locally · M5 Pro</span><strong class="number">0.084<span style="font-size:23px;letter-spacing:0"> ms</span></strong><h3>P95 model step</h3><p>Dataset 2, one replay pass: candidate + baseline prediction and any arriving-label update. Exported candidate artifact: 34.4 kB.</p><p class="small">Excludes sensor extraction, instrument, network and UI latency. M4 Pro also verified. DGX training was not used.</p></div></div>
<div class="controls"><label>Public dataset<select id="dataset"><option value="1">Dataset 1 · 542 samples</option><option value="2">Dataset 2 · 3,317 samples</option></select></label><label>Feedback delay<select id="delay"><option value="5">5 samples</option><option value="20">20 samples</option></select></label><label>Prediction metric<select id="metric"><option value="rmse">RMSE</option><option value="p90">P90 absolute error</option></select></label></div>
<div class="twocol"><div><svg id="chart" role="img" aria-label="Measurement request rate versus prediction error"></svg><p class="small">Average over every sampling offset at each rate. Both methods receive identical requested labels at identical times. Offsets share the same stream; they are not independent trials. Axes show normalized prediction errors, not physical units.</p></div><div><h3 id="condition"></h3><p>Same 20% request budget. Development-defined error threshold exceedance:</p><div class="meter"><span>GRAPE</span><div class="bar"><i id="basebar" style="background:#89979d"></i></div><strong id="baserate"></strong></div><div class="meter"><span>REFLEX</span><div class="bar"><i id="refbar"></i></div><strong id="refrate"></strong></div><strong class="number" id="reduction"></strong><p id="ci" class="small"></p><div class="callout" id="gate"></div></div></div>
<h3>All four conditions · equal measurement budget</h3><div class="scroll"><table><thead><tr><th>Dataset / delay</th><th>RMSE reduction</th><th>P90 reduction</th><th>Large-error reduction</th><th>95% interval*</th></tr></thead><tbody id="rows"></tbody></table></div><p class="small">*Interval for relative large-error reduction. Paired circular moving-block bootstrap: 5,000 replicates, 50-sample blocks. Conditional intervals do not correct model selection or data reuse. Negative values mean a regression. Different conditions have different development-defined thresholds.</p><div class="callout"><b>Measurement efficiency: the 50% reduction target failed overall.</b><br>Dataset 2 met the fixed noninferiority margins, but GRAPE also did. We cannot attribute those measurement savings to REFLEX. Dataset 1 failed. No measured fab productivity, yield or cost-saving percentage is claimed.</div><p><button id="download" class="secondary">Download all 40 condition means · CSV</button> <a href="https://github.com/2fe2000/reflex-metrology/tree/main/results/customer">Raw results & protocol ↗</a></p></section>
<section id="value"><div class="eyebrow">03 / From research to an economic outcome</div><h2>Sell a measured operating improvement.</h2><div class="grid"><article class="card"><h3>Land: one process owner</h3><p>Hypothesis: a process/metrology lead or equipment OEM wants fewer unreliable predictions while results are delayed. Begin with paid data integration and a fresh chronological evaluation.</p><p><b>Pilot hypothesis:</b> ₩5–10M.<br><b>Integration hypothesis:</b> ₩20–50M.<br>Pricing is unvalidated; no paid REFLEX customer.</p></article><article class="card"><h3>Prove: an operational gate</h3><p>Agree the physical tolerance and false-negative ceiling first. Then measure actual requests, post-maintenance recovery, engineer hours and marginal measurement costs on a fresh stream.</p><p>Only reduce sampling after the quality gate passes. Start in shadow mode, with existing process decisions intact.</p></article><article class="card"><h3>Expand: learning across chambers</h3><p>Vision: retain useful process experience, adapt across chambers, and shorten stabilization when materials or recipes change. Package a local runtime through equipment partners.</p><p class="small">Cross-chamber transfer and faster next-generation process development are future goals. Customer data access and demonstrated transfer would be advantages; no moat established yet.</p></article></div>
<div class="dark"><span class="tag warn">Illustrative scenario · not measured savings</span><h3>What could fewer physical checks be worth?</h3><div class="controls"><label>Monthly checks<input id="checks" type="number" min="0" max="100000000" value="5000"></label><label>Target reduction (%)<input id="saving" type="number" min="0" max="100" value="20"></label><label>Marginal cost / check (KRW)<input id="cost" type="number" min="0" max="100000000" value="10000"></label></div><strong class="number" id="roi"></strong><p id="roi_detail"></p><p class="small">Assumed checks × assumed reduction × assumed marginal cost. This excludes fixed equipment cost and does not imply an equal increase in fab throughput. The present benchmark has not established this 20% reduction. No currency conversion used.</p></div></section>
<section><div class="eyebrow">04 / Review, reproduce, verify</div><h2>Built in the event window. Evidence you can inspect.</h2><p>The published Taipei build session is November 11, 2026, 18:45–22:45 UTC+8 (10:45–14:45 UTC). The repository was created on GitHub at 12:55:11 UTC. Commits and CI provide dated records; they do not independently prove when every line was first authored.</p><div class="grid"><article class="card"><h3>Existing resources</h3><p>Public GRAPE equations and data, NumPy and scientific Python libraries. Upstream code and model references are attributed. Published GRAPE scores are not claimed to be reproduced.</p></article><article class="card"><h3>Event implementation</h3><p>Portable replay, causal delayed-label handling, timestamped filters, bounded regime state, online expert weighting, comparisons, tests, interface and narrated demo.</p></article><article class="card"><h3>Judge path</h3><p><a href="https://github.com/2fe2000/reflex-metrology">Repository overview ↗</a><br><a href="https://github.com/2fe2000/reflex-metrology/commits/main/">Commit history ↗</a><br><a href="https://github.com/2fe2000/reflex-metrology/actions">GitHub verification runs ↗</a></p><p class="small">Repository currently private by owner choice. A judge needs repository access or a later public release. This page is not a submission receipt.</p></article></div><details><summary>Methods and limitations</summary><p>Frozen V7 weights. Two public, anonymized exported-feature datasets; delay 5 and 20 samples; sampling periods 1, 2, 5, 10 and 20; all offsets; no condition discarded. The customer protocol and development thresholds precede this evaluation, but the evaluation streams were used in earlier model development. Error threshold = GRAPE period-5 development absolute-error 95th percentile, separately for each dataset and delay.</p><p>Column-order semantics in upstream exported data remain unresolved. We consistently retain the same exported order; this is not a complete authors' benchmark reproduction. No real maintenance labels, physical quality specifications, actual elapsed instrument delays, fab costs, defect labels or yield were observed. The Bayesian posterior is capped at 32 hypotheses; total UI history is not constant-memory.</p></details><ol class="sources"><li><a href="https://news.skhynix.com/en/gauss-labs-and-sk-hynix-present-ai-papers-at-spie-al-2024/">SK hynix, February 2024: real deployment and process variability</a></li><li><a href="https://news.skhynix.com/en/sk-hynix-and-gauss-labs-present-ai-based-semiconductor-virtual-metrology-research-at-spie-al-2026/">SK hynix, February 2026: equipment matching and overlay research</a></li><li><a href="https://www.nist.gov/publications/artificial-intelligence-open-and-scaled-data-sharing-semiconductor-manufacturing">NIST, November 2025: semiconductor data-sharing and virtual metrology</a></li><li><a href="https://github.com/cheonwoolee/GRAPE">GRAPE code & attribution</a> · <a href="https://arxiv.org/abs/2611.00806">paper</a> · <a href="https://arxiv.org/abs/0710.3742">Bayesian online changepoints</a> · <a href="https://arxiv.org/abs/2611.03230">posterior-merging inspiration</a></li><li><a href="https://luma.com/compiled-poy7">c0mpiled Taipei: schedule and submission rules</a></li></ol></section></main><footer>REFLEX · Public-data research prototype · Adapt while measurements are in flight.</footer>
<script>const evidence=__EVIDENCE__;const $=id=>document.getElementById(id);const fmt=(v,n=2)=>Number(v).toFixed(n);function draw(){let ds=+$('dataset').value,d=+$('delay').value,m=$('metric').value,c=evidence.conditions.find(x=>x.dataset===ds&&x.delay===d),s=c.same_budget,f=evidence.frontier.filter(x=>x.dataset===ds&&x.delay===d),rates=[5,10,20,50,100],ys=f.map(x=>x[m]),min=Math.min(...ys)*.94,max=Math.max(...ys)*1.06,X=i=>70+i*135,Y=v=>285-(v-min)/(max-min)*230;let svg='<rect width="680" height="350" fill="#f4f1e9"/>';for(let i=0;i<5;i++){let v=min+(max-min)*i/4;svg+=`<line x1="70" x2="610" y1="${Y(v)}" y2="${Y(v)}" stroke="#cbd0cc"/><text x="58" y="${Y(v)+4}" text-anchor="end" fill="#5c6870" font-size="12">${fmt(v,3)}</text><text x="${X(i)}" y="312" text-anchor="middle" fill="#142838" font-size="13">${rates[i]}%</text>`}for(let method of ['grape','reflex']){let points=rates.map((r,i)=>[X(i),Y(f.find(x=>x.method===method&&x.period===100/r)[m])]),color=method==='reflex'?'#225dff':'#89979d';svg+=`<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="3"/>`;points.forEach(p=>svg+=`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="${color}"/>`)}svg+='<text x="70" y="20" fill="#225dff" font-size="14">● REFLEX</text><text x="200" y="20" fill="#718087" font-size="14">● GRAPE</text><text x="340" y="345" text-anchor="middle" fill="#5c6870" font-size="12">Requested measurements / all samples · lower error is better</text>';$('chart').setAttribute('viewBox','0 0 680 355');$('chart').innerHTML=svg;$('condition').textContent=`Dataset ${ds} · ${d}-sample feedback delay`;let b=s.exceedance_rates.grape*100,r=s.exceedance_rates.reflex*100;$('baserate').textContent=fmt(b)+'%';$('refrate').textContent=fmt(r)+'%';$('basebar').style.width='90%';$('refbar').style.width=(90*r/b)+'%';$('reduction').textContent=fmt(s.exceedance_reduction_pct)+'% ↓';$('ci').textContent=`Relative reduction; ${fmt(s.exceedance_reduction_pp)} percentage points. Conditional 95% interval: ${s.exceedance_reduction_pct_ci95.map(v=>fmt(v)).join(' to ')}%. Threshold: ${fmt(c.threshold,4)}.`;$('gate').textContent=c.half_measurements.reflex10.ci_pass?'Half the measurements: noninferiority margins met here. GRAPE also passes; this is not a REFLEX-specific saving.':'Half the measurements: noninferiority margins NOT met here. Do not claim 50% measurement savings.'}
$('rows').innerHTML=evidence.conditions.map(c=>{let s=c.same_budget;return `<tr><td>D${c.dataset} / ${c.delay} samples</td><td class="${s.rmse_improvement_pct<0?'bad':'good'}">${fmt(s.rmse_improvement_pct)}%</td><td>${fmt(s.p90_improvement_pct)}%</td><td>${fmt(s.exceedance_reduction_pct)}%</td><td>${s.exceedance_reduction_pct_ci95.map(v=>fmt(v)).join(' to ')}%</td></tr>`}).join('');['dataset','delay','metric'].forEach(id=>$(id).addEventListener('change',draw));function roi(){let c=Math.max(0,+$('checks').value||0),r=Math.max(0,Math.min(100,+$('saving').value||0)),cost=Math.max(0,+$('cost').value||0);$('roi').textContent='₩'+Math.round(c*r/100*cost).toLocaleString('en-US')+' / month';$('roi_detail').textContent=`Illustration: ${Math.round(c*r/100).toLocaleString('en-US')} fewer checks, if a future quality-qualified pilot achieves the ${r}% target. Not current measured savings.`}['checks','saving','cost'].forEach(id=>$(id).addEventListener('input',roi));$('download').onclick=()=>{let cols=Object.keys(evidence.frontier[0]),csv=[cols.join(','),...evidence.frontier.map(r=>cols.map(c=>r[c]).join(','))].join('\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='REFLEX_customer_benchmark_means.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};draw();roi();</script></html>'''
html=html.replace('__EVIDENCE__',json.dumps(s,allow_nan=False))
for p in [R/'web/benchmark.html',R/'deliverables/REFLEX_customer_benchmark.html']:p.write_text(html)
print('Customer dashboard built: 40 means, 4 paired comparisons, standalone HTML.')
